// Delimiter characters for slugify (boltons.strutils.slugify defaults).
// Horizontal tab, newline, vertical tab, form feed, carriage return, space,
// and the ASCII punctuation set. Backslash is NOT a delimiter.
export const DELIM_CHARS =
  '\t\n\v\f\r ' +
  '!"#$%&\'()*+,-./:;<=>?@[]^_`{|}~';

// Character class source fragment for use in a RegExp.
const DELIM_CLASS = '\\t\\n\\v\\f\\r !"#$%&\'()*+,\\-./:;<=>?@\\[\\]\\^_`{|}~';

// Matches a maximal run of one or more delimiter characters.
export const DELIM_RUN_RE = new RegExp('[' + DELIM_CLASS + ']+', 'g');

