import { DELIM_RUN_RE } from './delimiters.mjs';

// slugify with boltons defaults: delim='_', lower=True, ascii=False.
// 1. Lowercase the input.
// 2. Replace every maximal run of delimiter chars with a single '_'.
// 3. Strip leading/trailing underscores.
// 4. If the result is empty but the input was non-empty, return '_'.
export function slugify(text) {
  const result = text
    .toLowerCase()
    .replace(DELIM_RUN_RE, '_')
    .replace(/^_+|_+$/g, '');
  if (result === '' && text !== '') {
    return '_';
  }
  return result;
}

