// Minimal reimplementation of the Python argparse behavior for:
//   parser.add_argument('--a', type=str, required=True)
// with prog name fixed to "test4_executable".

export const PROG = 'test4_executable';

export const USAGE = `usage: ${PROG} [-h] --a A`;

export const HELP_TEXT =
  USAGE + '\n' +
  '\n' +
  'options:\n' +
  '  -h, --help  show this help message and exit\n' +
  '  --a A\n';

// Python argparse's negative-number matcher.
const NEGATIVE_NUMBER_RE = /^-\d+$|^-\d*\.\d+$/;

function printHelpAndExit() {
  process.stdout.write(HELP_TEXT);
  process.exit(0);
}

function errorAndExit(message) {
  process.stderr.write(USAGE + '\n' + PROG + ': error: ' + message + '\n');
  process.exit(2);
}

// A token "looks like an option" (and thus cannot be --a's value) when it
// starts with '-', is not the single dash "-", and is not a negative number.
function looksLikeOption(token) {
  if (token === undefined) return false;
  if (!token.startsWith('-')) return false;
  if (token === '-') return false;
  if (NEGATIVE_NUMBER_RE.test(token)) return false;
  return true;
}

// Parses the argument vector (already stripped of node/script path).
// On success returns { a: <string> }. On help/error, exits the process
// exactly like Python argparse (help: stdout, exit 0; error: stderr, exit 2).
export function parseArgs(argv) {
  let aValue; // undefined until --a is seen; last occurrence wins
  const extras = [];
  let afterDoubleDash = false;

  let i = 0;
  while (i < argv.length) {
    const token = argv[i];

    if (afterDoubleDash) {
      extras.push(token);
      i += 1;
      continue;
    }

    // A bare "--": this argparse version has no positionals, so "--" itself
    // becomes an extra and everything after it is never treated as an option.
    if (token === '--') {
      afterDoubleDash = true;
      extras.push(token);
      i += 1;
      continue;
    }

    // -h or any unambiguous long-option abbreviation of --help
    // (options are --help and --a, so --h/--he/--hel/--help all select help).
    if (token === '-h' ||
        (token.startsWith('--') && token.length > 2 && '--help'.startsWith(token))) {
      printHelpAndExit();
    }

    // --a=VALUE form (including --a= which yields the empty string).
    if (token.startsWith('--a=')) {
      aValue = token.slice('--a='.length);
      i += 1;
      continue;
    }

    // --a VALUE form: consume the next token unless it looks like an option.
    if (token === '--a') {
      const next = argv[i + 1];
      if (next === undefined || looksLikeOption(next)) {
        errorAndExit('argument --a: expected one argument');
      }
      aValue = next;
      i += 2;
      continue;
    }

    // Unrecognized options and stray positionals become extras.
    extras.push(token);
    i += 1;
  }

  if (aValue === undefined) {
    errorAndExit('the following arguments are required: --a');
  }
  if (extras.length > 0) {
    errorAndExit('unrecognized arguments: ' + extras.join(' '));
  }

  return { a: aValue };
}

